def solution(input_str):
    # Parse hexagonal board
    lines = input_str.strip().split('\n')

    # Convert to coordinates
    # In hexagonal packing, we use axial coordinates
    positions = []
    for i, line in enumerate(lines):
        parts = line.split()
        for j, ch in enumerate(parts):
            if ch == 'O':
                positions.append((i, j))

    # Check if board is empty
    if not positions:
        return "Lillebror\n"

    # Convert to frozenset for memoization
    state = frozenset(positions)

    # Game analysis using memoization
    # Since this is impartial, we use Grundy numbers theory
    # But for small states, we can just compute if current position is winning

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def is_winning(pos_set):
        if not pos_set:
            return False  # No moves = losing

        # Try all possible moves and see if any leads to losing state
        for direction in range(3):  # 3 directions in hexagonal grid
            # Direction vectors for hex grid
            if direction == 0:
                dirs = [(0, 1), (0, -1)]  # Horizontal rows
            elif direction == 1:
                dirs = [(1, 0), (-1, 0)]  # One diagonal
            else:
                dirs = [(1, -1), (-1, 1)]  # Another diagonal

            for dr, dc in dirs:
                # Find chains in this direction
                for start in sorted(pos_set):
                    r, c = start
                    chain = [start]
                    curr_r, curr_c = r, c

                    while True:
                        next_pos = (curr_r + dr, curr_c + dc)
                        if next_pos in pos_set:
                            chain.append(next_pos)
                            curr_r, curr_c = curr_c
                            curr_c += dc
                            if next_pos == chain[-1]:
                                break
                        else:
                            break

                    # Try removing k consecutive chocolates from chain
                    for k in range(1, len(chain) + 1):
                        to_remove = frozenset(chain[:k])
                        new_state = pos_set - to_remove

                        if not is_winning(new_state):
                            return True

        # If no winning move found, this is losing
        return False

    if is_winning(state):
        return "Karlsson\n"
    else:
        return "Lillebror\n"
