def solution(input_str):
    # Game theory impartial game on hexagonal board
    # Compute if first player has winning strategy

    rows = input_str.strip().split('\n')
    hadocs = []

    for i, r in enumerate(rows):
        for j, c in enumerate(r.split()):
            if c == 'O':
                hadocs.append((i, j))

    if not hadocs:
        return "Lillebror\n"

    state = frozenset((i, j) for i, j in hadocs)

    @lru_cache(maxsize=None)
    def nim(state):
        if not state:
            return 0
        # Compute Grundy number via mex
        reachable = set()
        for d in [(0, 1), (1, 0), (1, -1)]:
            for start in state:
                r, c = start
                chn = [start]
                while True:
                    nr, nc = r + d[0], c + d[1]
                    if (nr, nc) in state:
                        chn.append((nr, nc))
                        r, c = nr, nc
                    else:
                        break
                for k in range(1, len(chn) + 1):
                    ms = state - frozenset(chn[:k])
                    reachable.add(nim(ms))
        mex = 0
        while mex in reachable:
            mex += 1
        return mex

    return "Karlsson\n" if nim(state) != 0 else "Lillebror\n"
