            components += 1
            queue = deque([i])
            visited[i] = True
            colors[i] = 0
            while queue:
                u = queue.popleft()
                for v, rel in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        colors[v] = colors[u] ^ rel
                        queue.append(v)
                    else:
                        if colors[v] != colors[u] ^ rel:
                            return '0'

    MOD = 1000000007
    # Each connected component can be colored in 2 ways, but global color flip
    # gives the same relationship pattern, so total = 2^(components-1)
    ans = pow(2, components - 1, MOD)
    return str(ans)
