    n, m = map(int, lines[0].split())

    # T-shape patterns - each is a list of (row, col) offsets
    # Starting from the center cell, these are the 4 rotation orientations
    patterns = [
        # Top bar, stem pointing up
        [(-1, 0), (0, -1), (0, 0), (0, 1)],
        # Bottom bar, stem pointing down  
        [(1, 0), (0, -1), (0, 0), (0, 1)],
        # Left bar, stem pointing right
        [(0, -1), (-1, 0), (0, 0), (0, 1)],
        # Right bar, stem pointing left
        [(0, 1), (-1, 0), (0, 0), (0, -1)]
    ]

    best_count = 0
    best_grid = None
    best_usage = 0

    grid = [[0 for _ in range(m)] for _ in range(n)]
    letter = ord('A')

    def can_place(r, c, cells):
        for dr, dc in cells:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < n and 0 <= nc < m):
                return False
            if grid[nr][nc] != 0:
                return False
        return True

    def place(grid, r, c, cells):
        for dr, dc in cells:
            grid[r + dr][c + dc] = 1

    def remove(grid, r, c, cells):
        for dr, dc in cells:
            grid[r + dr][c + dc] = 0

    def solve(idx):
        nonlocal best_count, best_grid, best_usage, grid
        count = sum(sum(row) for row in grid) // 4
        if count > best_count:
            best_count = count
            best_grid = [row[:] for row in grid]

        if idx > 4:
            return

        for i in range(idx, 3):
            for r in range(n):
                for c in range(m):
                    if can_place(r, c, patterns[i]):
                        place(grid, r, c, patterns[i])
                        solve(i + 1)
                        if best_count > count:
                            break
                        elif best_count == count:
                            break
                        remove(grid, r, c, patterns[i])
                        if best_count > count:
                            break

    # Try different orderings for efficiency
    import itertools
    for perm in itertools.permutations(range(4)):
        solve(perm[0])
        if best_count * 4 >= n * m:
            break

    # Generate output
    result = str(best_count) + '\n'

    # Mark cells with letters
    for r in range(n):
        row_out = []
        for c in range(m):
            if grid[r][c] != 0:
                # Convert to letter
                letter_idx = (grid[r][c] - 1) % 26
                row_out.append(chr(ord('A') + letter_idx))
            else:
                row_out.append('.')
        result += ''.join(row_out) + '\n'

    return result.strip() + '\n'
