Looking at this problem, I need to write a solution that determines if a graph can be oriented to become strongly connected, and if so, output the orientation.

This is a classic problem solvable by checking for bridges. According to Robbins' theorem, a connected undirected graph can be oriented to form a strongly connected directed graph if and only if it is 2-edge-connected (has no bridges).

```python
from collections import defaultdict
import sys
sys.setrecursionlimit(300000)

def solution(input_string):
    lines = input_string.strip().split('\n')
    if not lines or not lines[0]:
        return "0\n"

    try:
        n, m = map(int, lines[0].split())
    except:
        return "0\n"

    if n == 0 or m == 0:
        return "0\n"

    # Build the graph
    adj = defaultdict(list)
    original_edges = []

    for i in range(m):
        try:
            parts = lines[i + 1].split()
            u, v = int(parts[0]), int(parts[1])
            adj[u].append(v)
            adj[v].append(u)
            original_edges.append((u, v))
        except:
            return "0\n"

    # Basic check: for 2-edge-connected, need at least n edges
    if m < n:
        return "0\n"

    # Find bridges using Tarjan's algorithm
    disc = [-1] * (n + 1)
    low = [-1] * (n + 1)
    timer = [0]
    has_bridge = False

    def dfs_find_bridges(u, p=0):
        nonlocal has_bridge
        disc[u] = low[u] = timer[0]
        timer[0] += 1

        for v in adj[u]:
            if v == p:
                continue
            if disc[v] != -1:
                low[u] = min(low[u], disc[v])
            else:
                dfs_find_bridges(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    has_bridge = True

    # Start DFS from node 1 (graph is connected)
    dfs_find_bridges(1)

    if has_bridge:
        return "0\n"

    # No bridges found - graph is 2-edge-connected
    # Now we need to orient edges to make it strongly connected

    # For a 2-edge-connected graph, we can find an Eulerian-like traversal
    # and orient edges consistently

    visited = [False] * (n + 1)
    orientation = {}  # store result as (start, end)
    edge_outputs = []

    # Use DFS to build the orientation
    def dfs_orient(u, p=-1):
        visited[u] = True

        # For each edge from u to unvisited neighbor v
        dfs_orient(u)

    # Better approach: use DFS and orient tree edges appropriately
    # We'll track edge indices
    edge_map = {}  # frozenset({u,v}) -> (u,v) orientation
    result_ordering = []

    visited = [False] * (n + 1)
    dfs_order = []

    def dfs_visit(u):
        visited[u] = True
        dfs_order.append(u)

        for v in adj[u]:
            if not visited[v]:
                dfs_visit(v)
                # Tree edge: orient u -> v
                edge_key = frozenset({u, v})
                edge_map[edge_key] = (u, v)

    dfs_visit(1)

    # Now process remaining (back) edges
    for u in range(1, n + 1):
        for v in adj[u]:
            if u > v:  # avoid double counting and tree edges already processed
                continue
            edge_key = frozenset({u, v})
            if edge_key in edge_map:
                continue
            # Back edge, orient towards DFS order
            if dfs_order.index(v) > dfs_order.index(u):
                edge_map[edge_key] = (u, v)
            else:
                edge_map[edge_key] = (v, u)

    # Build final output
    output_lines = []
    for u, v in original_edges:
        key = frozenset({u, v})
        if key in edge_map:
            output_lines.append(f"{edge_map[key][0]} {edge_map[key][1]}")
        else:
            output_lines.append(f"{u} {v}")

    return "\n".join(output_lines) + "\n"
