def solution(input_str):
    lines = input_str.strip().split('\n')
    s1 = lines[0]
    s2 = lines[1]
    virus = lines[2]

    n1, n2, m = len(s1), len(s2), len(virus)

    # Compute KMP failure function (pi array)
    pi = [0] * m
    j = 0
    for i in range(1, m):
        while j > 0 and virus[i] != virus[j]:
            j = pi[j - 1]
        if virus[i] == virus[j]:
            j += 1
        pi[i] = j

    def get_next_state(curr_k, char):
        """Get next KMP state after seeing character"""
        j = curr_k
        while j > 0 and virus[j] != char:
            j = pi[j - 1]
        if j < m and virus[j] == char:
            j += 1
        return j

    # dp[i][j][k] = max LCS length using s1[:i] and s2[:j] ending with virus state k
    dp = [[[0] * (m + 1) for _ in range(n2 + 1)] for _ in range(n1 + 1)]

    # parent[i][j][k] = (prev_i, prev_j, prev_k) for reconstruction
    parent = [[[-1, -1, -1] for _ in range(m + 1)] for _ in range(n2 + 1)] for _ in range(n1 + 1)]

    # Fill DP table
    for i in range(1, n1 + 1):
        for j in range(1, n2 + 1):
            for k in range(m + 1):
                curr = dp[i][j][k]

                # Option 1: Skip character from s1 (remain at dp[i-1][j][k])
                skip1 = dp[i - 1][j][k]
                if skip1 >= curr:
                    curr = skip1
                    parent[i][j][k] = [i - 1, j, k]

                # Option 2: Skip character from s2 (remain at dp[i][j-1][k])
                skip2 = dp[i][j - 1][k]
                if skip2 > curr:
                    curr = skip2
                    parent[i][j][k] = [i, j - 1, k]

                # Option 3: Match both characters if they're equal
                if s1[i - 1] == s2[j - 1]:
                    prev_k = 0
                    if k > 0:
                        prev_k = k
                        # Check if state k-1 could lead here (in reverse transition)
                        # Actually we need to find previous state that transitions to k
                    new_k = get_next_state(k, s1[i - 1])
                    if new_k >= k and new_k < m:
                        prev_val = dp[i - 1][j - 1][k]
                        if prev_val + 1 > curr:
                            curr = prev_val + 1
                            parent[i][j][k] = [i - 1, j - 1, k]

                dp[i][j][k] = curr

    # Find maximum valid answer
    max_k = max_k = 0
    max_len = 0
    for k in range(m + 1):
        if dp[n1][n2][k] > max_len:
            max_len = dp[n1][n2][k]
            max_k = k

    if max_len == 0:
        return "0"

    # Reconstruct the LCS by backtracking
    result = []
    i, j, k = n1, n2, max_k

    while i > 0 or j > 0:
        prev_i, prev_j, prev_k = parent[i][j][k]
        if prev_i == -1 and prev_j == -1:
            break

        if i == prev_i and j == prev_j:
            # Transition happened via matching
            # Get the character involved
            if s1[i - 1] == s2[j - 1]:
                result.append(s1[i - 1])
            i, j, k = prev_i, prev_j, prev_k
        elif i > prev_i:
            # Came from skipping s1, restore to that state
            i, j, k = prev_i, prev_j, prev_k
        else:
            # Came from skipping s2
            i, j, k = prev_i, prev_j, prev_k

    return ''.join(reversed(result))
