def solution(input_str):
    lines = input_str.strip().split('\n')
    s1, s2, virus = lines[0].strip(), lines[1].strip(), lines[2].strip()

    n1, n2, m = len(s1), len(s2), len(virus)

    # KMP preprocess
    pi = [0] * m
    j = 0
    for i in range(1, m):
        while j > 0 and virus[i] != virus[j]:
            j = pi[j-1]
        if virus[i] == virus[j]:
            j += 1
        pi[i] = j

    def next_state(k, c):
        while k > 0 and virus[k] != c:
            k = pi[k-1]
        if k < m and virus[k] == c:
            k += 1
        return k

    # DP: dp[i][j][k] = max LCS length
    # parent[i][j][k] = parent state
    dp = [[[0]*(m+1) for _ in range(n2+1)] for _ in range(n1+1)]
    parent = [[[-1,-1,-1]]*(m+1) for _ in range(n2+1)] for _ in range(n1+1)

    for i in range(n1+1):
        for j in range(n2+1):
            for k in range(m+1):
                # Skip s1 char
                if i > 0 and dp[i-1][j][k] > dp[i][j][k]:
                    dp[i][j][k] = dp[i-1][j][k]
                    parent[i][j][k] = (i-1, j, k)
                # Skip s2 char  
                if j > 0 and dp[i][j-1][k] > dp[i][j][k]:
                    dp[i][j][k] = dp[i][j-1][k]
                    parent[i][j][k] = (i, j-1, k)

    for i in range(1, n1+1):
        for j in range(1, n2+1):
            if s1[i-1] == s2[j-1]:
                for pk in range(m+1):
                    nk = next_state(pk, s1[i-1])
                    if nk < m:
                        nv = dp[i-1][j-1][pk] + 1
                        if nv > dp[i][j][nk]:
                            dp[i][j][nk] = nv
                            parent[i][j][nk] = (i-1, j-1, pk)

    # Find max
    max_len = 0
    for k in range(m+1):
        if dp[n1][n2][k] > max_len:
            max_len = dp[n1][n2][k]

    if max_len == 0:
        return "0"

    # Reconstruct
    res = []
    i, j, k = n1, n2, max_len
    while i > 0 and j > 0 and k >= 0:
        p = parent[i][j][k]
        if p == (-1, -1, -1):
            break

        pi_val, pj_val, pk_val = p

        if pk_val != k:  # Match occurred
            res.append(s1[i-1])
            i, j, k = pi_val, pj_val, pk_val
        else:  # Skip
            if pi_val < i:
                i = pi_val
            else:
                j = pj_val
                k = pk_val

    return ''.join(res)
