Looking at this problem, I need to find if a car can return to its starting intersection with the odometer showing 0. The key insight is that within each strongly connected component (SCC), cycles can be traversed multiple times, and we need to find if there exists a cycle with length L such that (s + L) % t == 0.

This is determined by whether s is divisible by gcd(g, t), where g is the GCD of all cycle lengths in the SCC containing the starting vertex.

```python
import sys
from math import gcd

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        a, b, l = map(int, lines[i].split())
        adj[a].append((b, l))

    q = int(lines[m + 1])
    queries = []
    for i in range(q):
        v, s, t = map(int, lines[m + 2 + i].split())
        queries.append((v, s, t))

    sys.setrecursionlimit(max(10**6, 2 * n + 100))

    visited = [False] * (n + 1)
    discovery = [0] * (n + 1)
    in_stack = [False] * (n + 1)
    lowest = [0] * (n + 1)
    stack = []
    id_counter = 0
    scc_count = 0
    scc = [0] * (n + 1)

    def find_scc(u):
        nonlocal id_counter, scc_count
        discovery[u] = lowest[u] = id_counter
        id_counter += 1
        stack.append(u)
        in_stack[u] = True

        for v, l in adj[u]:
            if not visited[v]:
                visited[v] = True
                find_scc(v)
                lowest[u] = min(lowest[u], lowest[v])
            elif v in stack and in_stack[v]:
                lowest[u] = min(lowest[u], discovery[v])

        if lowest[u] == discovery[u]:
            while True:
                node = stack.pop()
                in_stack[node] = False
                scc[node] = scc_count
                if node == u:
                    break
            scc_count += 1

    for i in range(1, n + 1):
        if not visited[i]:
            find_scc(i)

    scc_gcd = {}

    for scc_id in range(scc_count):
        scc_nodes = [i for i in range(1, n + 1) if scc[i] == scc_id]
        if not scc_nodes:
            continue

        g = 0

        dist_map = {}
        stack_trans = []

        visited_trans = set()

        for root in scc_nodes:
            if root in visited_trans:
                continue

            dist_map[root] = 0
            stack_trans = [root]
            visited_trans.add(root)
            parent_map = {root: -1}

            while stack_trans:
                u = stack_trans.pop()

                for v, l in adj[u]:
                    if v in scc_nodes and v not in visited_trans:
                        visited_trans.add(v)
                        dist_map[v] = dist_map[u] + l
                        parent_map[v] = u
                        stack_trans.append(v)

                        for w, _ in adj[v]:
                            if w in scc_nodes and w == parent_map[v]:
                                continue
                            if parent_map.get(v) is None:
                                cycle_len = abs(dist_map[u] - dist_map[w]) + l
                                g = gcd(g, cycle_len)

        scc_gcd[scc_id] = g

    result = []
    for v, s, t in queries:
        if v > n:
            result.append("NO")
            continue

        if s == 0:
            result.append("YES")
            continue

        scc_id = scc[v]
        if scc_id >= scc_count:
            result.append("NO")
            continue

        g = scc_gcd.get(scc_id, 0)

        if g == 0:
            result.append("YES")
            continue

        if s % gcd(g, t) == 0:
            result.append("YES")
        else:
            result.append("NO")

    return '\n'.join(result)
