The key insight is to construct s1 and s2 using patterns that control the number of "AC" substrings. Using "AC" patterns with "B" fillers allows precise control.

```python
def solution(input_str):
    k, x, n, m = map(int, input_str.strip().split())

    def count_ac(s):
        count = 0
        for i in range(len(s) - 1):
            if s[i] == 'A' and s[i+1] == 'C':
                count += 1
        return count

    # Construct s1 and s2 with AC patterns and B fillers
    s1 = "AC" * (n // 2) + "B" * (n % 2)
    s2 = "AC" * (m // 2) + "B" * (m % 2)

    if k == 1:
        res = s1
    elif k == 2:
        res = s2
    else:
        s_prev = [s1, s2]
        for _ in range(k - 2):
            s_prev.append(s_prev[-2] + s_prev[-1])
        res = s_prev[-1]

    if count_ac(res) == x:
        return f"{s1}\n{s2}"
    else:
        return "Happy new year!"
